package dev.kb896.aiusage.rear

import android.graphics.Path
import androidx.core.graphics.PathParser
import dev.kb896.aiusage.data.PanelTheme

/**
 * The GLASS theme's glyphs.
 *
 * GENERATED by tools/glass-icons.py from Lucide — do not edit the path data by hand.
 *
 * Lucide, ISC licence, https://lucide.dev. Chosen over drawing them here, which was the
 * first attempt and the wrong one: ten hand-built glyphs are ten chances to get a
 * proportion slightly wrong, and they were not consistent with each other. A real set is
 * drawn to one grid with one stroke weight by people doing nothing else, and it shows
 * immediately at twenty units.
 *
 * Every icon is 24x24 with a 2-unit stroke and round caps and joins, which is the whole
 * reason the set hangs together — and the reason [STROKE] and [VIEWPORT] are stated once
 * here rather than per glyph.
 *
 * THESE ARE SQUARE, and ORIGINAL's traced glyphs are not: its battery is tall and narrow,
 * its camera wide. So the footprint is a property of the THEME rather than of the panel,
 * and everything that lays out against a glyph asks for it through Glyphs.aspect. That
 * was the alternative to squeezing a square icon into a 0.58-wide box, which is a small
 * battery beside a full-size clock.
 */
object GlassIcons {

    /** How it is painted. The transport is solid; it is what gets pressed. */
    enum class Ink { LINE, SOLID }

    /** One glyph: the Lucide path data, and how to paint it. */
    class Outline(val data: String, val ink: Ink) {
        /** Parsed lazily and kept — PathParser is a scan, and this is asked per frame. */
        val path: Path by lazy { PathParser.createPathFromPathData(data) }
    }

    /** The grid every icon is drawn on. */
    const val VIEWPORT = 24f

    /** Lucide's stroke weight, in viewport units. */
    const val STROKE = 2f

    /** Square, all of them. */
    const val ASPECT = 1f

    /** Lucide "clock". */
    val CLOCK = Outline(
        "M2.0,12.0 a10.0,10.0 0 1,0 20.0,0 a10.0,10.0 0 1,0 -20.0,0 Z M12 6v6l4 2",
        Ink.LINE,
    )
    /** Lucide "calendar". */
    val CALENDAR = Outline(
        "M8 2v3 M16 2v3 M5.0,3.0 H19.0 A2.0,2.0 0 0,1 21.0,5.0 V19.0 A2.0,2.0 0 0,1 19.0,21.0 H5.0 A2.0,2.0 0 0,1 3.0,19.0 V5.0 A2.0,2.0 0 0,1 5.0,3.0 Z M3 9h18",
        Ink.LINE,
    )
    /** Lucide "battery". */
    val BATTERY = Outline(
        "M 22 14 L 22 10 M4.0,6.0 H16.0 A2.0,2.0 0 0,1 18.0,8.0 V16.0 A2.0,2.0 0 0,1 16.0,18.0 H4.0 A2.0,2.0 0 0,1 2.0,16.0 V8.0 A2.0,2.0 0 0,1 4.0,6.0 Z",
        Ink.LINE,
    )
    /** Lucide "battery-charging". */
    val CHARGING = Outline(
        "m11 7-3 5h4l-3 5 M14.856 6H16a2 2 0 0 1 2 2v8a2 2 0 0 1-2 2h-2.935 M22 14v-4 M5.14 18H4a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h2.936",
        Ink.LINE,
    )
    /** Lucide "camera". */
    val CAMERA = Outline(
        "M13.997 4a2 2 0 0 1 1.76 1.05l.486.9A2 2 0 0 0 18.003 7H20a2 2 0 0 1 2 2v9a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V9a2 2 0 0 1 2-2h1.997a2 2 0 0 0 1.759-1.048l.489-.904A2 2 0 0 1 10.004 4z M9.0,13.0 a3.0,3.0 0 1,0 6.0,0 a3.0,3.0 0 1,0 -6.0,0 Z",
        Ink.LINE,
    )
    /** Lucide "play". */
    val PLAY = Outline(
        "M5 5a2 2 0 0 1 3.008-1.728l11.997 6.998a2 2 0 0 1 .003 3.458l-12 7A2 2 0 0 1 5 19z",
        Ink.SOLID,
    )
    /** Lucide "pause". */
    val PAUSE = Outline(
        "M15.0,3.0 H18.0 A1.0,1.0 0 0,1 19.0,4.0 V20.0 A1.0,1.0 0 0,1 18.0,21.0 H15.0 A1.0,1.0 0 0,1 14.0,20.0 V4.0 A1.0,1.0 0 0,1 15.0,3.0 Z M6.0,3.0 H9.0 A1.0,1.0 0 0,1 10.0,4.0 V20.0 A1.0,1.0 0 0,1 9.0,21.0 H6.0 A1.0,1.0 0 0,1 5.0,20.0 V4.0 A1.0,1.0 0 0,1 6.0,3.0 Z",
        Ink.SOLID,
    )
    /** Lucide "skip-back". */
    val PREV = Outline(
        "M17.971 4.285A2 2 0 0 1 21 6v12a2 2 0 0 1-3.029 1.715l-9.997-5.998a2 2 0 0 1-.003-3.432z M3 20V4",
        Ink.SOLID,
    )
    /** Lucide "skip-forward". */
    val NEXT = Outline(
        "M21 4v16 M6.029 4.285A2 2 0 0 0 3 6v12a2 2 0 0 0 3.029 1.715l9.997-5.998a2 2 0 0 0 .003-3.432z",
        Ink.SOLID,
    )
    /** Lucide "volume". */
    val VOLUME_OFF = Outline(
        "M11 4.702a.705.705 0 0 0-1.203-.498L6.413 7.587A1.4 1.4 0 0 1 5.416 8H3a1 1 0 0 0-1 1v6a1 1 0 0 0 1 1h2.416a1.4 1.4 0 0 1 .997.413l3.383 3.384A.705.705 0 0 0 11 19.298z",
        Ink.SOLID,
    )

    private val pairs: Map<PanelIcons.Icon, Outline> = mapOf(
        PanelIcons.CLOCK to CLOCK,
        PanelIcons.CALENDAR to CALENDAR,
        PanelIcons.BATTERY to BATTERY,
        PanelIcons.CHARGING to CHARGING,
        PanelIcons.CAMERA to CAMERA,
        PanelIcons.PLAY to PLAY,
        PanelIcons.PAUSE to PAUSE,
        PanelIcons.PREV to PREV,
        PanelIcons.NEXT to NEXT,
        PanelIcons.VOLUME_OFF to VOLUME_OFF,
    )

    /** The glass counterpart of a traced glyph, or null if it has none. */
    fun of(icon: PanelIcons.Icon): Outline? = pairs[icon]
}

/**
 * Which glyphs the panel draws, and how big their boxes are, in the theme that is on.
 *
 * THE FOOTPRINT IS THE THEME'S, NOT THE GLYPH'S. ORIGINAL traces its glyphs from a
 * terminal font and inherits that font's proportions — a tall narrow battery, a wide
 * camera; GLASS uses a square grid. The panel lays out against these numbers in half a
 * dozen places, so asking the icon directly is asking the wrong question: it answers for
 * one theme and is silently wrong in the other.
 */
object Glyphs {

    fun aspect(icon: PanelIcons.Icon, theme: PanelTheme): Float =
        if (theme.isGlass && GlassIcons.of(icon) != null) GlassIcons.ASPECT else icon.aspect
}
